from pathlib import Path
p=Path('scripts/coop_session.gd')
s=p.read_text()
s=s.replace('const PROTOCOL := "slapdash-cafe-life-17"','const PROTOCOL := "slapdash-cafe-life-18"')
s=s.replace('var remote_customers := {}\n','var remote_customers := {}\nvar sleeping_peers := {}\n')
s=s.replace('\tremote_customers.clear()\n\tplayer_poses.clear()','\tremote_customers.clear()\n\tsleeping_peers.clear()\n\tplayer_poses.clear()',1)
s=s.replace('''func _peer_left(id: int) -> void:\n\tmembers.erase(id)\n\tplayer_poses.erase(id)\n''','''func _peer_left(id: int) -> void:\n\tmembers.erase(id)\n\tsleeping_peers.erase(id)\n\tplayer_poses.erase(id)\n''',1)
s=s.replace('''\t\tbroadcast_roster()\n\t\t_status("Участник вышел. Его незаконченный проход отменён; рабочие рецепты сохранены.")\n''','''\t\tbroadcast_roster()\n\t\t_broadcast_sleep_state()\n\t\t_try_finish_sleep()\n\t\t_status("Участник вышел. Его незаконченный проход отменён; рабочие рецепты сохранены.")\n''',1)
marker='''@rpc("authority", "call_remote", "reliable", 0)\nfunc _roster(value: Dictionary) -> void: members = value\n\n'''
insert='''@rpc("authority", "call_remote", "reliable", 0)\nfunc _roster(value: Dictionary) -> void: members = value\n\nfunc sleep_participants() -> Array:\n\tvar result: Array = []\n\tif members.is_empty():\n\t\tresult.append(1)\n\telse:\n\t\tfor id in members: result.append(int(id))\n\treturn result\n\nfunc local_sleep_bed() -> int:\n\treturn int(sleeping_peers.get(local_id(),-1))\n\nfunc local_sleeping() -> bool:\n\treturn local_sleep_bed() >= 0\n\nfunc sleeping_peer_for_bed(bed_index: int) -> int:\n\tfor id in sleeping_peers:\n\t\tif int(sleeping_peers[id]) == bed_index: return int(id)\n\treturn 0\n\nfunc sleep_status_text() -> String:\n\tvar total := sleep_participants().size()\n\tvar ready := 0\n\tfor id in sleep_participants():\n\t\tif sleeping_peers.has(id): ready += 1\n\treturn "Спят %d/%d" % [ready,total]\n\nfunc clear_sleeping() -> void:\n\tsleeping_peers.clear()\n\nfunc _peer_world_position(id: int) -> Vector3:\n\tif id == 1: return game.player.global_position\n\tvar raw: Array = player_poses.get(id,{}).get("position",[])\n\treturn Vector3(raw[0],raw[1],raw[2]) if raw.size()==3 else Vector3.INF\n\nfunc _broadcast_sleep_state() -> void:\n\tif not connected or guest: return\n\tfor id in members:\n\t\tif id != 1: _sleep_state.rpc_id(id,sleeping_peers)\n\n@rpc("authority", "call_remote", "reliable", 0)\nfunc _sleep_state(value: Dictionary) -> void:\n\tsleeping_peers = value.duplicate(true)\n\nfunc _try_finish_sleep() -> bool:\n\tif game.service.progress.shift != "night": return false\n\tvar participants := sleep_participants()\n\tif participants.is_empty(): return false\n\tfor id in participants:\n\t\tif not sleeping_peers.has(id): return false\n\tvar error: String = game.service.next_day()\n\tif not error.is_empty(): return false\n\tsleeping_peers.clear()\n\t_broadcast_sleep_state()\n\tgame.service.announce("Все легли спать. Начался день %d." % game.service.progress.day)\n\tgame.save_cafe()\n\treturn true\n\nfunc _sleep_action(sender: int, value: Dictionary) -> String:\n\tvar action := str(value.get("action",""))\n\tif action == "wake":\n\t\tif sleeping_peers.has(sender):\n\t\t\tsleeping_peers.erase(sender)\n\t\t\t_broadcast_sleep_state()\n\t\treturn ""\n\tif game.service.progress.shift != "night": return "Спать можно после окончания смены."\n\tif game.service.training_for(sender) != null: return "Сначала заверши готовку."\n\tif game.shop.carried(sender) >= 0 or game.service.progress.garland_builder == sender: return "Сначала освободи руки."\n\tif int(game.laboratory.state.get("owner",0)) == sender and str(game.laboratory.state.get("phase","idle")) in ["fill","tune"]: return "Сначала заверши активный этап лаборатории."\n\tvar bed := int(value.get("bed",-1))\n\tif bed < 0 or bed >= game.annex.PLAYER_BED_COUNT: return "Кровать не найдена."\n\tvar center: Vector3 = game.annex.player_bed_center(bed)\n\tif _peer_world_position(sender).distance_to(center) > 4.5: return "Подойди к кровати."\n\tvar occupant := sleeping_peer_for_bed(bed)\n\tif occupant > 0 and occupant != sender: return "Эта кровать уже занята."\n\tsleeping_peers[sender] = bed\n\t_broadcast_sleep_state()\n\tif not _try_finish_sleep():\n\t\tvar name := str(members.get(sender,"Повар"))\n\t\tgame.service.announce("%s лёг спать · %s" % [name,sleep_status_text()])\n\treturn ""\n\n'''
if marker not in s: raise SystemExit('roster marker missing')
s=s.replace(marker,insert,1)
old='''\tif action == "next_day":\n\t\tif action in ["lab_begin", "garland_begin", "next_day"] and sender != 1:\n\t\t\tmessage_to(sender, "Это действие подтверждает хозяин кафе.")\n\t\t\treturn\n\t\tvar target: Vector3 = game.development.night_action_position(action, value)\n\t\tvar location: Array = player_poses.get(sender, {}).get("position", [])\n\t\tvar peer_position: Vector3 = game.player.global_position if sender == 1 else Vector3(location[0], location[1], location[2]) if location.size() == 3 else Vector3.INF\n\t\tif peer_position.distance_to(target) > 4.5: return\n\t\tvar error: String = game.service.night_action(action, value, sender)\n\t\tif not error.is_empty(): message_to(sender, error)\n\t\telse: game.save_cafe()\n\t\treturn\n'''
new='''\tif action in ["sleep","wake"]:\n\t\tvar error: String = _sleep_action(sender,value)\n\t\tif not error.is_empty(): message_to(sender,error)\n\t\treturn\n'''
if old not in s: raise SystemExit('next_day action block missing')
s=s.replace(old,new,1)
s=s.replace('''func advance(delta: float) -> void:\n\t_draw_players(delta)\n\tif not connected: return\n''','''func advance(delta: float) -> void:\n\t_draw_players(delta)\n\tif not guest and game.service.progress.shift != "night" and not sleeping_peers.is_empty():\n\t\tsleeping_peers.clear()\n\t\t_broadcast_sleep_state()\n\tif not connected: return\n''',1)
s=s.replace('''\tvar data := {"laboratory": game.laboratory.state.duplicate(true), "protocol": PROTOCOL, "stations": entries, "players": player_poses, "customers": customers, "served": game.service.served, "revenue": game.service.revenue, "missed": game.service.missed, "open": game.service.open_for_business, "progression": game.service.progress.snapshot()}\n''','''\tvar data := {"laboratory": game.laboratory.state.duplicate(true), "sleeping": sleeping_peers.duplicate(true), "protocol": PROTOCOL, "stations": entries, "players": player_poses, "customers": customers, "served": game.service.served, "revenue": game.service.revenue, "missed": game.service.missed, "open": game.service.open_for_business, "progression": game.service.progress.snapshot()}\n''',1)
s=s.replace('''\tplayer_poses = data.players\n\tvar ids: Array = []\n''','''\tplayer_poses = data.players\n\tsleeping_peers = data.get("sleeping",{}).duplicate(true)\n\tvar ids: Array = []\n''',1)
s=s.replace('''\t\tavatar.perform(pose, target, held)\n\t\tavatar.caption.text = str(members[id])\n''','''\t\tavatar.perform(pose, target, held)\n\t\tavatar.caption.text = str(members[id])\n\t\tif sleeping_peers.has(id):\n\t\t\tgame.annex.settle_player_avatar(avatar,int(sleeping_peers[id]))\n\t\t\tavatar.caption.text += "\\nСпит"\n''',1)
p.write_text(s)
